custom_css:
/* MoodTube theme: Sweet Universe: Night. Celestial stationery: ivory paper, plum and lilac, a sacred-geometry medallion around the cover, little planets and sparkles. */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,600&display=swap');

/* palette; each variant sets --t-head (header text), --t-title, --t-sub, --t-ctl (buttons and sliders),
   --t-pbg / --t-ptext / --t-pline / --t-pdim (panels and windows) */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal, #moodtube-dock {
  --t-ivory: #f4f1eb;
  --t-lilac: #b9a7d3;
  --t-faint: #d6cbe6;
  --t-lav: #8a6db5;
  --t-plum: #5b3f7a;
  --t-plum2: #6e5094;
  --t-night: #3b2556;
  --t-ink: #4a3466;
  --mt-bg-primary: var(--t-pbg);
  --mt-bg-secondary: var(--t-pbg);
  --mt-bg-input: var(--t-pbg);
  --mt-accent: var(--t-plum);
  --mt-accent-hover: var(--t-plum2);
  --mt-border: var(--t-pline);
  --mt-text: var(--t-ptext);
  --mt-text-dim: var(--t-pdim);
  --mt-text-on-accent: var(--t-ivory);
  --mt-text-strong: var(--t-ptext);
  --mt-divider: var(--t-pline);
  --mt-overlay: rgba(40, 24, 60, 0.55);
  --mt-modal-shadow: none;
  --mt-pl-spotify-tab: var(--t-plum);
  --mt-pl-spotify-tab-text: var(--t-ivory);
}

.mt-progress {
  --mt-slider-track: color-mix(in srgb, var(--t-ctl) 22%, transparent);
  --mt-slider-track-height: 1px;
  --mt-slider-track-radius: 0px;
  --mt-slider-progress: var(--t-ctl);
  --mt-slider-thumb-size: 14px;
  --mt-slider-thumb-bg: var(--t-thumb) center / 14px 14px no-repeat;
  --mt-slider-thumb-bg-hover: var(--t-thumb) center / 14px 14px no-repeat;
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 0;
  --mt-slider-thumb-shadow: none;
}
.mt-volume {
  --mt-slider-track: color-mix(in srgb, var(--t-ctl) 22%, transparent);
  --mt-slider-track-height: 1px;
  --mt-slider-track-radius: 0px;
  --mt-slider-progress: var(--t-ctl);
  --mt-slider-thumb-size: 8px;
  --mt-slider-thumb-bg: var(--t-ctl);
  --mt-slider-thumb-bg-hover: var(--t-plum2);
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 50%;
  --mt-slider-thumb-shadow: none;
}

.mt-player {
  container-type: size;
  padding: 60px 22px 34px;
  background: var(--t-ivory);
  border: none;
  border-radius: 2px;
  box-shadow: 0 10px 26px rgba(59, 37, 86, 0.22);
  backdrop-filter: none;
  color: var(--t-ink);
  font-family: 'Cormorant Garamond', Georgia, serif;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

#moodtube-mini-player, #moodtube-mini-player *, #mt-settings-modal, #mt-settings-modal *, .mt-fab, .mt-fab *, .mt-pl-modal, .mt-pl-modal *, #moodtube-dock, #moodtube-dock * {
  text-shadow: none;
}

/* double hairline frame with diamonds in the corners, sparkles around */
.mt-slot-bg::before, .mt-slot-bg::after { content: ''; position: absolute; pointer-events: none; }
.mt-slot-bg::before { inset: 8px; border: 1px solid var(--t-frame1); }
.mt-slot-bg::after { inset: 12px; border: 1px solid var(--t-frame2); }

/* header: spaced caps, a second line below it */
.mt-player-header { top: 18px; left: 22px; right: 22px; display: block; text-align: center; }
.mt-player-header-title { display: block; font-size: 11px; font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; color: var(--t-head); }
.mt-player-header-title::after { content: var(--t-motto); display: block; margin-top: 3px; font-size: 10px; font-weight: 600; letter-spacing: 0.24em; color: var(--t-head2); white-space: nowrap; }
.mt-player-status { display: none; }

.mt-window-btn {
  top: 15px;
  width: 16px;
  height: 16px;
  padding: 0;
  font-size: 10px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  color: var(--t-head2);
  cursor: pointer;
  transition: color 0.15s;
}
.mt-window-btn:hover { color: var(--t-head); }
.mt-window-btn.mt-btn-close { right: 17px; }
.mt-window-btn.mt-btn-settings { right: 34px; }
.mt-window-btn.mt-btn-search { right: 51px; }
.mt-btn-search.mt-is-open { color: var(--t-head) !important; }
.mt-player:has(.mt-panel[style*="flex"]) .mt-window-btn { color: var(--t-pdim); }

.mt-player-body { gap: 6px; justify-content: flex-start; }

/* the cover inside a sacred-geometry medallion with small planets */
.mt-cover {
  width: 116px;
  height: 116px;
  margin: 0 auto 2px;
  overflow: visible;
  border-radius: 50%;
  border: none;
  box-shadow: none;
  background: transparent;
}
img.mt-cover-img {
  position: absolute;
  inset: 7px;
  width: calc(100% - 14px);
  height: calc(100% - 14px);
  border-radius: 50%;
  object-fit: cover;
  filter: var(--t-cover-filter);
}
.mt-slot-cover-bg { inset: 7px; border-radius: 50%; background: var(--t-cover-idle); }
.mt-slot-cover { border-radius: 0; }
.mt-cover-hole { display: none; }
.mt-cover::after {
  content: '';
  position: absolute;
  z-index: 3;
  inset: -22px -26px;
  pointer-events: none;
  background:
    radial-gradient(circle 2.2px at 8px 33px, #fff 0 60%, transparent 100%),
    radial-gradient(circle 8px at 11px 36px, #e9def6 0, #a58bcc 55%, #7d5fa6 92%, transparent 100%),
    radial-gradient(circle 1.6px at calc(100% - 22px) 14px, #fff 0 60%, transparent 100%),
    radial-gradient(circle 5.5px at calc(100% - 20px) 16px, #e9def6 0, #a58bcc 55%, #7d5fa6 92%, transparent 100%),
    radial-gradient(circle 2px at calc(100% - 11px) calc(100% - 37px), #fff 0 60%, transparent 100%),
    radial-gradient(circle 7px at calc(100% - 9px) calc(100% - 34px), #e9def6 0, #a58bcc 55%, #7d5fa6 92%, transparent 100%);
}

.mt-track-info { padding: 0 24px; }
#moodtube-mini-player .mt-track-title {
  font-size: 28px;
  font-style: italic;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: 0;
  color: var(--t-title);
}
.mt-track-subtitle { margin-top: 0; font-size: 10px; font-weight: 600; letter-spacing: 0.26em; text-transform: uppercase; color: var(--t-sub); }
.mt-btn-favorite {
  top: 50%;
  right: 0;
  translate: 0 -50%;
  width: 20px;
  height: 20px;
  padding: 0;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--t-sub);
  cursor: pointer;
}
.mt-btn-favorite:hover, .mt-btn-favorite.mt-is-active { color: var(--t-title); }

.mt-progress { gap: 7px; margin-top: 2px; }
.mt-time-current, .mt-time-total { font-size: 11px; font-weight: 600; letter-spacing: 0.04em; color: var(--t-ctl-dim); }

/* buttons: hairline rings, Play filled plum */
.mt-controls { gap: 9px; justify-content: center; }
.mt-controls > .mt-btn {
  width: 30px;
  height: 30px;
  font-size: 12px;
  padding: 0;
  line-height: 1;
  box-sizing: border-box;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: transparent;
  border: 1px solid var(--t-ctl);
  color: var(--t-ctl);
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s, translate 0.1s;
}
.mt-controls > .mt-btn:hover { background: var(--t-ctl); color: var(--t-ctl-on); }
.mt-controls > .mt-btn:active { translate: 0 1px; }
.mt-controls > .mt-btn.mt-btn-play, .mt-controls > #moodtube-btn-playpause {
  width: 38px;
  height: 38px;
  font-size: 14px;
  background: var(--t-play-bg);
  border-color: var(--t-play-bg);
  color: var(--t-play-fg);
}
.mt-controls > .mt-btn.mt-btn-play:hover, .mt-controls > #moodtube-btn-playpause:hover { background: var(--t-play-hover); border-color: var(--t-play-hover); color: var(--t-play-fg); }
#moodtube-btn-playpause.fa-play { padding-left: 2px; }
.mt-controls > .mt-btn.mt-btn-ai.mt-is-busy { background: var(--t-plum); border-color: var(--t-plum); color: var(--t-ivory); animation: mt-sw-blink 0.9s steps(2) infinite; }
@keyframes mt-sw-blink { 50% { opacity: 0.5; } }

.mt-volume { gap: 6px; width: 84%; }
.mt-volume-low, .mt-volume-high, .mt-volume-icon { font-size: 10px; color: var(--t-ctl-dim); }

/* motto at the bottom */
.mt-player-body::after {
  content: var(--t-foot);
  position: absolute;
  left: 0;
  right: 0;
  bottom: -20px;
  text-align: center;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.24em;
  color: var(--t-foot-c);
  white-space: nowrap;
  pointer-events: none;
}

/* panels: a lined memo sheet */
.mt-panel {
  background: var(--t-pbg);
  color: var(--t-ptext);
  padding: 48px 20px 18px;
  border-radius: inherit;
}
.mt-panel::before { content: ''; position: absolute; inset: 8px; border: 1px solid var(--t-pline); pointer-events: none; }
.mt-panel-search { --mt-bg-primary: var(--t-pbg); }
.mt-panel-header { border-bottom: 1px solid var(--t-pline); padding-bottom: 6px; margin-bottom: 4px; }
.mt-panel-header-left { margin-right: 10px; }
.mt-panel-title { font-size: 12px; font-weight: 700; letter-spacing: 0.18em; text-transform: uppercase; color: var(--t-ptext); }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--t-pdim); }
.mt-panel-close:hover { color: var(--t-ptext); }
.mt-panel-list {
  background: repeating-linear-gradient(180deg, transparent 0 29px, var(--t-pline) 29px 30px);
  background-attachment: local;
}
.mt-queue-item { height: 30px; box-sizing: border-box; gap: 6px; padding: 0 4px; margin: 0; border: none; border-radius: 0; background: transparent; }
.mt-queue-item:hover { background: color-mix(in srgb, var(--t-lav) 10%, transparent); }
.mt-queue-item::before { content: '\2726'; flex-shrink: 0; width: 12px; font-size: 10px; color: transparent; }
.mt-queue-item.mt-is-current { background: transparent; }
.mt-queue-item.mt-is-current::before { color: var(--t-lav); }
.mt-queue-thumb { display: none; }
.mt-queue-title { color: var(--t-ptext); font-size: 14px; font-weight: 600; letter-spacing: 0; }
.mt-queue-item.mt-is-current .mt-queue-title { font-style: italic; color: var(--t-pcur); }
.mt-queue-now { color: var(--t-lav); }
.mt-queue-add { color: var(--t-pdim); }
.mt-queue-add:hover { color: var(--t-ptext); }
.mt-queue-dislike { background-color: var(--t-pdim); }
.mt-queue-dislike:hover { background-color: var(--t-ptext); }
.mt-queue-empty { color: var(--t-pdim); }

.mt-pl-tabs { border-bottom: 1px solid var(--t-pline); gap: 6px; }
.mt-pl-tab { font-size: 11px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--t-ptext); background: transparent; border: 1px solid var(--t-pline); border-radius: 999px; }
.mt-pl-tab.mt-is-active { background: var(--t-plum); border-color: var(--t-plum); color: var(--t-ivory); }
.mt-playlist-item { border-radius: 0; border-bottom: 1px solid var(--t-pline); background: transparent; }
.mt-playlist-item:hover { background: color-mix(in srgb, var(--t-lav) 10%, transparent); }
.mt-playlist-title { color: var(--t-ptext); font-weight: 700; font-size: 14px; }
.mt-pl-count { color: var(--t-pdim); }
.mt-pl-cover { border-radius: 50%; }
.mt-pl-tool { background: transparent; color: var(--t-ptext); border: 1px solid var(--t-pline); border-radius: 999px; }
.mt-pl-tool.mt-pl-play, .mt-pl-tool:hover { background: var(--t-plum); border-color: var(--t-plum); color: var(--t-ivory); }

#moodtube-search-input { background: transparent; color: var(--t-ptext); border: 1px solid var(--t-pline); border-radius: 999px; }
#moodtube-search-go { background: var(--t-plum); color: var(--t-ivory); border: none; border-radius: 999px; }
#moodtube-search-go:hover { background: var(--t-plum2); }

/* floating button: a plum disc with a little sparkle */
.mt-fab, .mt-fab.mt-fab-docked {
  background: var(--t-plum);
  border: 1px solid var(--t-lilac);
  border-radius: 50%;
  color: var(--t-ivory);
  box-shadow: 0 4px 12px rgba(59, 37, 86, 0.3);
}
.mt-fab::after { content: '\2726'; position: absolute; top: -1px; right: 1px; font-size: 12px; line-height: 1; color: var(--t-lilac); pointer-events: none; }
.mt-fab:hover, .mt-fab.mt-fab-docked:hover { background: var(--t-plum2); color: var(--t-ivory); }

.mt-pl-modal-box { background: var(--t-pbg); color: var(--t-ptext); border: 1px solid var(--t-pline); outline: 1px solid var(--t-pline); outline-offset: -6px; border-radius: 2px; box-shadow: 0 12px 30px rgba(59, 37, 86, 0.25); }
.mt-pl-modal-track { color: var(--t-ptext); font-weight: 700; font-style: italic; font-size: 16px; }
.mt-pl-option { color: var(--t-ptext); border: 1px solid var(--t-pline); border-radius: 999px; background: transparent; }
.mt-pl-option:hover { background: color-mix(in srgb, var(--t-lav) 12%, transparent); }
.mt-pl-option.mt-is-added { background: var(--t-plum); color: var(--t-ivory); border-color: var(--t-plum); }

/* settings: the same stationery */
#mt-settings-modal .mt-flex-container {
  background: var(--t-pbg);
  color: var(--t-ptext);
  border: 1px solid var(--t-pline);
  outline: 1px solid var(--t-pline);
  outline-offset: -6px;
  border-radius: 2px;
  box-shadow: 0 16px 40px rgba(59, 37, 86, 0.3);
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 15px;
}
#mt-settings-modal .mt-header h3 { font-style: italic; font-weight: 600; font-size: 1.8em; letter-spacing: 0; color: var(--t-ptext); }
#mt-settings-modal .mt-close { color: var(--t-pdim); }
#mt-settings-modal .mt-close:hover { color: var(--t-ptext); }
#mt-settings-modal .mt-subpanel { background: color-mix(in srgb, var(--t-lav) 6%, transparent); border: 1px solid var(--t-pline); border-radius: 2px; }
#mt-settings-modal .mt-btn-test {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: var(--t-plum);
  color: var(--t-ivory);
  border: none;
  border-radius: 999px;
  padding: 8px 16px;
  font-weight: 700;
  letter-spacing: 0.08em;
  cursor: pointer;
}
#mt-settings-modal .mt-btn-test:hover { background: var(--t-plum2); }
.mt-tag, .mt-genre-tag, .mt-mood-tag, .mt-scenario-tag { background: transparent; border: 1px solid var(--t-pline); color: var(--t-ptext); border-radius: 999px; padding: 4px 11px; }
.mt-tag:hover, .mt-genre-tag:hover, .mt-mood-tag:hover, .mt-scenario-tag:hover { border-color: var(--t-lav); }
.mt-tag.active, .mt-genre-tag.active, .mt-mood-tag.active, .mt-scenario-tag.active { background: var(--t-plum); border-color: var(--t-plum); color: var(--t-ivory); font-weight: 700; }

.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar, .mt-pl-modal-box ::-webkit-scrollbar { width: 4px; height: 4px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track, .mt-pl-modal-box ::-webkit-scrollbar-track { background: transparent; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb, .mt-pl-modal-box ::-webkit-scrollbar-thumb { background: var(--t-lilac); border-radius: 99px; }

/* sizes and modes */
@container (max-width: 640px) { .mt-player.moodtube-row-layout .mt-volume { display: none; } }

.mt-player.moodtube-row-layout#moodtube-mini-player { padding: 38px 22px 20px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-header { top: 16px; text-align: left; right: 80px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-header-title::after { display: none; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-body { flex-direction: row; align-items: center; justify-content: flex-start; gap: 14px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-body::after { display: none; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover { width: 70px; height: 70px; margin: 0; }
.mt-player.moodtube-row-layout#moodtube-mini-player img.mt-cover-img { inset: 5px; width: calc(100% - 10px); height: calc(100% - 10px); }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-slot-cover-bg { inset: 5px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover::after { display: none; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-track-info { min-width: 120px; max-width: 200px; flex: 0 1 180px; align-items: flex-start; text-align: left; padding: 0 22px 0 0; }
#moodtube-mini-player.moodtube-row-layout .mt-track-title { font-size: 22px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-progress { flex: 1 1 110px; min-width: 90px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls { gap: 5px; flex-shrink: 0; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > .mt-btn { width: 28px; height: 28px; font-size: 11px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > .mt-btn.mt-btn-play,
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > #moodtube-btn-playpause { width: 34px; height: 34px; font-size: 13px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-volume { width: 76px; flex-shrink: 0; }
.mt-player.moodtube-row-layout .mt-slot-scene { background-size: 11px 11px, 11px 11px, 11px 11px, 11px 11px, 0 0, 0 0, 0 0; }

@container (max-height: 220px) {
  .mt-player:not(.moodtube-row-layout) .mt-cover { width: 80px; height: 80px; }
  .mt-player:not(.moodtube-row-layout) .mt-cover::after, .mt-player:not(.moodtube-row-layout) .mt-player-body::after { display: none; }
  #moodtube-mini-player:not(.moodtube-row-layout) .mt-track-title { font-size: 22px; }
}
@container (max-width: 190px) {
  .mt-player .mt-controls { gap: 4px; }
  .mt-player .mt-controls > .mt-btn { width: 26px; height: 26px; font-size: 11px; }
  .mt-player .mt-controls > .mt-btn.mt-btn-play, .mt-player .mt-controls > #moodtube-btn-playpause { width: 30px; height: 30px; font-size: 12px; }
  .mt-player .mt-cover::after, .mt-player .mt-player-body::after { display: none; }
  .mt-player-header-title::after { display: none; }
}

/* dock strip */
#moodtube-dock { font-family: 'Cormorant Garamond', Georgia, serif; background: var(--t-pbg); border-bottom: 1px solid var(--t-pline); }
#moodtube-dock .mt-dock-title { font-family: 'Cormorant Garamond', Georgia, serif; font-style: italic; font-weight: 600; font-size: 18px; line-height: 1.05; color: var(--t-ptext); }
#moodtube-dock .mt-dock-subtitle { font-family: 'Cormorant Garamond', Georgia, serif; font-weight: 600; font-size: 10px; letter-spacing: 0.24em; text-transform: uppercase; color: var(--t-pdim); }
#moodtube-dock .mt-dock-inner .mt-dock-cover { border: 1px solid var(--t-lilac); }

/* ===== Night: starry plum top, ivory bottom ===== */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal, #moodtube-dock {
  --t-head: #f4f1eb;
  --t-head2: #d8c8f0;
  --t-title: #ffffff;
  --t-sub: #d8c8f0;
  --t-ctl: #5b3f7a;
  --t-ctl-on: #f4f1eb;
  --t-ctl-dim: #8a6db5;
  --t-play-bg: #5b3f7a;
  --t-play-hover: #6e5094;
  --t-play-fg: #f4f1eb;
  --t-thumb: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M12%200L14.2%209.8%2024%2012%2014.2%2014.2%2012%2024%209.8%2014.2%200%2012%209.8%209.8Z%27%20fill%3D%27%235b3f7a%27%2F%3E%3C%2Fsvg%3E");
  --t-frame1: rgba(185, 167, 211, 0.75);
  --t-frame2: rgba(185, 167, 211, 0.32);
  --t-pbg: #3b2556;
  --t-ptext: #f4f1eb;
  --t-pline: rgba(216, 200, 240, 0.26);
  --t-pdim: #c6b3e6;
  --t-pcur: #ffffff;
  --t-foot-c: #8a6db5;
  --t-motto: 'SWEETER TOGETHER';
  --t-foot: 'SAME STARS';
  --t-cover-filter: saturate(0.8);
  --t-cover-idle: radial-gradient(circle, #ffffff 0, #d8c8f0 35%, #7d5fa6 75%, #4a3466 100%);
  --t-split: 226px;
}
