/* wide row, low window and the panel under the tavern header: all night, light controls */
.mt-player.moodtube-row-layout, .mt-player.mt-player-docked { --t-split: 100%; }
.mt-player.moodtube-row-layout, .mt-player.mt-player-docked {
  --t-foot-c: #c6b3e6;
  --t-ctl: #d8c8f0;
  --t-ctl-on: #3b2556;
  --t-ctl-dim: #c6b3e6;
  --t-play-bg: #d8c8f0;
  --t-play-hover: #ffffff;
  --t-play-fg: #3b2556;
  --t-thumb: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M12%200L14.2%209.8%2024%2012%2014.2%2014.2%2012%2024%209.8%2014.2%200%2012%209.8%209.8Z%27%20fill%3D%27%23d8c8f0%27%2F%3E%3C%2Fsvg%3E");
}
@container (max-height: 220px) {
  .mt-player-body {
    --t-ctl: #d8c8f0;
    --t-ctl-on: #3b2556;
    --t-ctl-dim: #c6b3e6;
    --t-play-bg: #d8c8f0;
    --t-play-hover: #ffffff;
    --t-play-fg: #3b2556;
  }
  .mt-slot-bg { --t-split: 100%; }
}

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Cormorant Garamond', Georgia, serif;
  --mt-dock-cover-radius: 50%;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 50%;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
